package main

import (
	"context"
	"fmt"

	"github.com/google/uuid"
	"github.com/jmoiron/sqlx"
)

// catalogTables maps the catalog kind used by catalogRef to its table.
var catalogTables = map[string]string{
	"issue_types": "issue_types",
	"priorities":  "priorities",
	"resolutions": "resolutions",
}

// catalogRef is a placeholder for a catalog item id. Catalog ids are generated by the database when the
// organization already has its catalogs (the migrations create them for the default organization), so the
// dataset cannot choose them. persist resolves each reference inside its transaction. An empty legacy key
// selects the organization default.
type catalogRef struct {
	org    uuid.UUID
	table  string
	legacy string
}

// catalogRow is one default catalog item of a seeded organization.
type catalogRow struct {
	name, icon, color, legacy string
	level, position           int
	isDefault                 bool
}

var defaultIssueTypeRows = []catalogRow{
	{name: "Épica", icon: "epic", color: "purple", level: 1, position: 0, legacy: "epic"},
	{name: "Historia", icon: "story", color: "green", position: 1, legacy: "story"},
	{name: "Tarea", icon: "task", color: "blue", position: 2, isDefault: true, legacy: "task"},
	{name: "Error", icon: "bug", color: "red", position: 3, legacy: "bug"},
	{name: "Subtarea", icon: "subtask", color: "teal", level: -1, position: 4, legacy: "subtask"},
}

var defaultPriorityRows = []catalogRow{
	{name: "Máxima", icon: "chevrons-up", color: "red", position: 0, legacy: "critical"},
	{name: "Alta", icon: "arrow-up", color: "orange", position: 1, legacy: "high"},
	{name: "Media", icon: "minus", color: "amber", position: 2, isDefault: true, legacy: "medium"},
	{name: "Baja", icon: "arrow-down", color: "blue", position: 3, legacy: "low"},
	{name: "Mínima", icon: "chevrons-down", color: "gray", position: 4, legacy: "low"},
}

var defaultResolutionRows = []catalogRow{
	{name: "Hecho", position: 0, isDefault: true},
	{name: "Descartado", position: 1},
	{name: "Duplicado", position: 2},
	{name: "No se reproduce", position: 3},
	{name: "No se hará", position: 4},
}

// buildCatalogs adds the default catalogs of an organization to the dataset. Rows that already exist (the
// migrations seed the default organization) are skipped by name.
func buildCatalogs(ds *dataset, orgID uuid.UUID, slug string) {
	types := ds.ignoreDuplicates("issue_types", "id", "organization_id", "name", "description", "icon", "color",
		"hierarchy_level", "position", "is_default", "legacy_key", "created_at", "updated_at")
	for _, row := range defaultIssueTypeRows {
		types.add(idFor("issue_type", slug, row.legacy), orgID, row.name, "", row.icon, row.color,
			row.level, row.position, row.isDefault, row.legacy, orgCreated, orgCreated)
	}
	priorities := ds.ignoreDuplicates("priorities", "id", "organization_id", "name", "icon", "color", "position",
		"is_default", "legacy_key", "created_at", "updated_at")
	for _, row := range defaultPriorityRows {
		priorities.add(idFor("priority", slug, row.name), orgID, row.name, row.icon, row.color, row.position,
			row.isDefault, row.legacy, orgCreated, orgCreated)
	}
	resolutions := ds.ignoreDuplicates("resolutions", "id", "organization_id", "name", "description", "position",
		"is_default", "created_at", "updated_at")
	for _, row := range defaultResolutionRows {
		resolutions.add(idFor("resolution", slug, row.name), orgID, row.name, "", row.position, row.isDefault,
			orgCreated, orgCreated)
	}
}

// resolveCatalogRef returns the id of the catalog item a reference points to, inside the transaction that
// inserts the dataset. Results are cached per reference.
func resolveCatalogRef(ctx context.Context, tx sqlx.QueryerContext, cache map[catalogRef]uuid.UUID, ref catalogRef) (uuid.UUID, error) {
	if id, ok := cache[ref]; ok {
		return id, nil
	}
	table, ok := catalogTables[ref.table]
	if !ok {
		return uuid.Nil, fmt.Errorf("seed: unknown catalog table %q", ref.table)
	}
	var (
		query string
		args  []any
	)
	switch {
	case ref.legacy == "":
		query = "SELECT id FROM " + table + " WHERE organization_id = $1 AND is_default"
		args = []any{ref.org}
	case table == "issue_types" || table == "priorities":
		query = "SELECT id FROM " + table + " WHERE organization_id = $1 AND legacy_key = $2 ORDER BY position LIMIT 1"
		args = []any{ref.org, ref.legacy}
	default:
		return uuid.Nil, fmt.Errorf("seed: catalog %s has no legacy keys", table)
	}
	var id uuid.UUID
	if err := sqlx.GetContext(ctx, tx, &id, query, args...); err != nil {
		return uuid.Nil, fmt.Errorf("seed: resolver %s (%s): %w", table, ref.legacy, err)
	}
	cache[ref] = id
	return id, nil
}
